/**
 * Jinx Banshee + Vortox: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Banshee
 * Wiki: https://wiki.bloodontheclocktower.com/Vortox
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Each test quotes the wiki text it encodes word
 * for word in a `// Wiki: "..."` comment (CLAUDE.md, Trevor 2026-11-01 and 2026-11-02).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { reliability } from '#lib/core/rules/night-info.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});
const script = scriptOf(['banshee', 'vortox', 'chef', 'empath', 'poisoner']);

const trueInfo = (s: Scenario) =>
	nightStepAlerts(s.game, 'banshee', s.characters).filter((a) => a.kind === 'true-info');

describe('Banshee + Vortox jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'banshee', 'vortox');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('banshee')?.name).toBe('Banshee');
		expect(data.byId.get('vortox')?.name).toBe('Vortox');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['banshee', 'vortox'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['banshee'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vortox'])).not.toContain(jinx);
	});

	describe('the Banshee killed by the Vortox is announced truly', () => {
		const killed = scenario(['banshee', 'vortox', 'chef', 'empath', 'poisoner'], {
			script
		}).dies('banshee', 'vortox');

		it("is data in the Vortox's rules", () => {
			expect(jinxRulesBetween('vortox', 'banshee')).toEqual({ trueInfo: {} });
		});

		it("the Vortox doesn't make the Banshee's announcement false, only other Townsfolk's", () => {
			// Wiki: "If the Vortox kills the Banshee, all players learn that the Banshee has died."
			const at = (id: string) => reliability(killed.game, killed.seat(id), id, killed.characters);
			expect(at('banshee').mustBeFalse).toBeUndefined();
			expect(at('chef')).toMatchObject({ mustBeFalse: true, falseBy: 'vortox' });
		});

		it("the Banshee's step says it is given truly, naming the Vortox", () => {
			// Wiki: "If the Vortox kills the Banshee, all players learn that the Banshee has died."
			expect(trueInfo(killed)).toMatchObject([
				{
					seatId: killed.seat('banshee'),
					source: { characterId: 'vortox', seatId: killed.seat('vortox') },
					works: true
				}
			]);
		});

		it('nothing to say while the Vortox has no working ability', () => {
			// Wiki: "If the Vortox kills the Banshee, all players learn that the Banshee has died."
			expect(trueInfo(killed.poisoned('vortox'))).toEqual([]);
		});
	});
});
